function railStep(rail){var card=rail.querySelector('.hsw-loop__card, .hsw-loop__lead, .hsw-loop__more');var gap=parseFloat(window.getComputedStyle(rail).columnGap||'12')||12;var width=card?card.getBoundingClientRect().width:200;return(width+gap)*(window.innerWidth>=768?2:1);}
function maxScroll(rail){return Math.max(0,rail.scrollWidth-rail.clientWidth);}
